{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts and tools, fasten a component to a marked location on the workbench, and leave tools on the bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "Primary surface for the target location and final tool placement.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["wooden table", "desk top"],
        "required_properties": ["flat", "stable", "accessible"]
      },
      {
        "id": "marked_location",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific spot on the workbench where fastening occurs.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly on table", "fixture", "marked spot"],
        "required_properties": ["accepts fastening", "located on workbench surface"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The part that fits into the marked location.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["plug", "screw", "insert", "part"],
        "required_properties": ["fits marked_location", "compatible with fastening"]
      },
      {
        "id": "fastening_equipment",
        "entity_kind": "OBJECT",
        "function": "Tool or device used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["tool", "device", "gripper", "hammer"],
        "required_properties": ["usable for fastening", "can be left on workbench"]
      },
      {
        "id": "storage_container",
        "entity_kind": "REGION",
        "function": "Closed structures to be searched for components and tools.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "cupboard"],
        "required_properties": ["closed", "storage capability", "accessible via opening mechanism"]
      }
    ],
    "functional_relations": [
      {
        "id": "fits_into",
        "relation": "The compatible_component must physically fit into the marked_location.",
        "participant_roles": ["compatible_component", "marked_location"]
      ,
      "required": true
      },
      {
        "id": "placed_on",
        "relation": "The fastening_equipment must be placed on the workbench_surface after use.",
        "participant_roles": ["fastening_equipment", "workbench_surface"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_for_items",
        "operation": "Search storage containers and open areas to locate the compatible_component and fastening_equipment.",
        "participant_roles": ["compatible_component", "fastening_equipment", "storage_container"],
        "operation_count": 1
      },
      {
        "id": "fasten_component",
        "operation": "Insert or attach the compatible_component to the marked_location using the fastening_equipment.",
        "participant_roles": ["compatible_component", "marked_location", "fastening_equipment"],
        "operation_count": 1
      },
      {
        "id": "place_equipment",
        "operation": "Set the fastening_equipment down on the workbench_surface.",
        "participant_roles": ["fastening_equipment", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench_surface": [
        {
          "label": "wooden table top",
          "visual_description": "Large flat wooden surface with drawers underneath and a monitor/cabinet behind."
        }
      ],
      "marked_location": [
        {
          "label": "black and yellow assembly",
          "visual_description": "Rectangular object on the table surface, appearing to be the fixture or target."
        }
      ],
      "compatible_component": [],
      "fastening_equipment": [],
      "storage_container": [
        {
          "label": "drawers under workbench",
          "visual_description": "Two blue drawers with handles, closed."
        },
        {
          "label": "cabinet next to workbench",
          "visual_description": "Tall blue cabinet with a handle, closed."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "drawers_under_workbench",
        "label": "drawers_under_workbench",
        "visual_description": "Two closed blue drawers beneath the table surface.",
        "reason": "Closed storage structure containing potential components or tools."
      },
      {
        "id": "cabinet_next_to_workbench",
        "label": "cabinet_next_to_workbench",
        "visual_description": "Closed blue cabinet standing beside the table.",
        "reason": "Closed storage structure containing potential components or tools."
      },
      {
        "id": "floor_area",
        "label": "floor_area",
        "visual_description": "Checkered floor pattern surrounding the furniture.",
        "reason": "Open space where items might be dropped."
      }
    ],
    "inspection_order": [
      "drawers_under_workbench",
      "cabinet_next_to_workbench",
      "floor_area"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
